import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/sheets/{sheetId}/settings")
@Validated
public class SettingsController {

    /** What the screen shows of a sheet's settings, each dated one as in force on the sheet's today; the clerk limit as text with two decimals
     *  (null when there is no limit), the floor as text with two decimals, the terms in days, and the late percent as text with two
     *  decimals, and the policy date (null when it is blank: the sheet's today stands in), and the
     *  period numbering from date (null when it is blank: off), and the terms each grade has of its own
     *  (a grade not in it takes the sheet's terms), and the cap as text with two decimals (null when
     *  there is no cap), and the floors, late percents and caps recorded, each from its from-date, earliest
     *  first (a claim takes the one in force on its date, or else the sheet's starting one); and the
     *  proof threshold as text with two decimals (null when there is none); and the permission matrix:
     *  for each action, the comma separated roles that may take it (blank: the standing rule). */
    public record SettingsView(String clerkLimit, String floor, int terms, String latePct, LocalDate policyDate,
            LocalDate periodNumberingFrom, Map<String, Integer> gradeTerms, String cap, List<DatedValue> floors,
            List<DatedValue> latePcts, List<DatedValue> caps, String proofThreshold,
            Map<String, String> permissions) {
        static SettingsView of(BigDecimal clerkLimit, BigDecimal floor, int terms, BigDecimal latePct,
                LocalDate policyDate, LocalDate periodNumberingFrom, Map<String, Integer> gradeTerms,
                BigDecimal cap, List<SettingValue> floors, List<SettingValue> latePcts,
                List<SettingValue> caps, BigDecimal proofThreshold, Map<String, String> permissions) {
            return new SettingsView(clerkLimit == null ? null : clerkLimit.setScale(2).toPlainString(),
                    floor.setScale(2).toPlainString(), terms, latePct.setScale(2).toPlainString(), policyDate,
                    periodNumberingFrom, gradeTerms, cap == null ? null : cap.setScale(2).toPlainString(),
                    floors.stream().map(DatedValue::of).toList(), latePcts.stream().map(DatedValue::of).toList(),
                    caps.stream().map(DatedValue::of).toList(),
                    proofThreshold == null ? null : proofThreshold.setScale(2).toPlainString(), permissions);
        }
    }

    /** A value a dated setting takes from a date, as text with two decimals; null when blank. */
    public record DatedValue(LocalDate from, String value) {
        static DatedValue of(SettingValue v) {
            return new DatedValue(v.getFrom(), v.getValue() == null ? null : v.getValue().setScale(2).toPlainString());
        }
    }

    /** A yyyy-mm-dd date, or blank. */
    static final String DATE = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*";

    /** A dated setting's form: its from-date is a date, or blank for the sheet's today. */
    interface Dated {
        String from();

        default LocalDate fromValue() {
            return date(from());
        }
    }

    /** A date typed (yyyy-mm-dd), or null when blank. */
    static LocalDate date(String value) {
        if (value == null || value.isBlank()) {
            return null;
        }
        try {
            return LocalDate.parse(value.trim());
        } catch (DateTimeParseException e) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Not a date: " + value.trim());
        }
    }

    /** The clerk limit form: 0.00 or more with up to two decimals, or blank for no limit; from a
     *  date, or blank for the sheet's today. */
    public record ClerkLimitForm(@Pattern(regexp = "\\s*(\\d{1,12}(\\.\\d{1,2})?)?\\s*") String value,
            @Pattern(regexp = DATE) String from) implements Dated {

        BigDecimal limitValue() {
            return value == null || value.isBlank() ? null : new BigDecimal(value.trim()).setScale(2);
        }
    }

    /** The cap form: 0.00 or more with up to two decimals, or blank for no cap; from a date, or
     *  blank for the sheet's today. */
    public record CapForm(@Pattern(regexp = "\\s*(\\d{1,12}(\\.\\d{1,2})?)?\\s*") String value,
            @Pattern(regexp = DATE) String from) implements Dated {

        BigDecimal capValue() {
            return value == null || value.isBlank() ? null : new BigDecimal(value.trim()).setScale(2);
        }
    }

    /** The proof threshold form: 0.00 or more with up to two decimals, or blank for none; from a
     *  date, or blank for the sheet's today. */
    public record ProofThresholdForm(@Pattern(regexp = "\\s*(\\d{1,12}(\\.\\d{1,2})?)?\\s*") String value,
            @Pattern(regexp = DATE) String from) implements Dated {

        BigDecimal thresholdValue() {
            return value == null || value.isBlank() ? null : new BigDecimal(value.trim()).setScale(2);
        }
    }

    /** The floor form: 0.00 or more with up to two decimals; from a date, or blank for the sheet's
     *  today. */
    public record FloorForm(@NotBlank @Pattern(regexp = "\\s*\\d{1,12}(\\.\\d{1,2})?\\s*") String value,
            @Pattern(regexp = DATE) String from) implements Dated {

        BigDecimal floorValue() {
            return new BigDecimal(value.trim()).setScale(2);
        }
    }

    /** The terms form: a whole number of days, 0 or more; from a date, or blank for the sheet's
     *  today. */
    public record TermsForm(@NotBlank @Pattern(regexp = "\\s*\\d{1,4}\\s*") String value,
            @Pattern(regexp = DATE) String from) implements Dated {

        int termsValue() {
            return Integer.parseInt(value.trim());
        }
    }

    /** The late percent form: a percent of 0.00 or more with up to two decimals; from a date, or
     *  blank for the sheet's today. */
    public record LatePctForm(@NotBlank @Pattern(regexp = "\\s*\\d{1,5}(\\.\\d{1,2})?\\s*") String value,
            @Pattern(regexp = DATE) String from) implements Dated {

        BigDecimal latePctValue() {
            return new BigDecimal(value.trim()).setScale(2);
        }
    }

    /** The policy date form: a date (yyyy-mm-dd), or blank for the sheet's today. */
    public record PolicyDateForm(@Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String value) {

        LocalDate policyDateValue() {
            return date(value);
        }
    }

    /** The period numbering from form: a date (yyyy-mm-dd), or blank for off. */
    public record PeriodNumberingFromForm(@Pattern(regexp = "\\s*(\\d{4}-\\d{2}-\\d{2})?\\s*") String value) {

        LocalDate fromValue() {
            return date(value);
        }
    }

    /** The permission form: a comma separated list of roles (clerk, steward), or blank for the
     *  standing rule. */
    public record PermissionForm(@Size(max = 200)
            @Pattern(regexp = "\\s*((clerk|steward)\\s*(,\\s*(clerk|steward)\\s*)*)?") String value) {

        /** The roles as stored: each once, comma separated with no spaces; "" when blank. */
        String rolesValue() {
            return value == null ? "" : String.join(",", Arrays.stream(value.split(","))
                    .map(String::trim).filter(r -> !r.isEmpty()).distinct().toList());
        }
    }

    private final SheetService service;

    public SettingsController(SheetService service) {
        this.service = service;
    }

    @GetMapping
    public SettingsView get(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return view(sheetId.trim());
    }

    /** The settings view of a sheet as the store holds it now. */
    private SettingsView view(String id) {
        return SettingsView.of(service.clerkLimit(id), service.floor(id), service.terms(id), service.latePct(id),
                service.policyDate(id), service.periodNumberingFrom(id), service.gradeTerms(id), service.cap(id),
                service.recorded(id, "floor"), service.recorded(id, "late-pct"),
                service.recorded(id, "cap"), service.proofThreshold(id), service.permissions(id));
    }

    /** The settings view of a sheet just saved. */
    private SettingsView view(Sheet sheet) {
        return view(sheet.getId());
    }

    @PutMapping("/clerk-limit")
    public SettingsView setClerkLimit(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody ClerkLimitForm form) {
        return view(service.setClerkLimit(sheetId.trim(), user.trim(), form.limitValue(), form.fromValue()));
    }

    @PutMapping("/floor")
    public SettingsView setFloor(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody FloorForm form) {
        return view(service.setFloor(sheetId.trim(), user.trim(), form.floorValue(), form.fromValue()));
    }

    @PutMapping("/terms")
    public SettingsView setTerms(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody TermsForm form) {
        return view(service.setTerms(sheetId.trim(), user.trim(), form.termsValue(), form.fromValue()));
    }

    @PutMapping("/terms/{grade}")
    public SettingsView setGradeTerms(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody TermsForm form) {
        return view(service.setGradeTerms(sheetId.trim(), user.trim(), grade, form.termsValue(), form.fromValue()));
    }

    @PutMapping("/late-pct")
    public SettingsView setLatePct(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody LatePctForm form) {
        return view(service.setLatePct(sheetId.trim(), user.trim(), form.latePctValue(), form.fromValue()));
    }

    @PutMapping("/policy-date")
    public SettingsView setPolicyDate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PolicyDateForm form) {
        return view(service.setPolicyDate(sheetId.trim(), user.trim(), form.policyDateValue()));
    }

    @PutMapping("/period-numbering-from")
    public SettingsView setPeriodNumberingFrom(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PeriodNumberingFromForm form) {
        return view(service.setPeriodNumberingFrom(sheetId.trim(), user.trim(), form.fromValue()));
    }

    @PutMapping("/cap")
    public SettingsView setCap(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody CapForm form) {
        return view(service.setCap(sheetId.trim(), user.trim(), form.capValue(), form.fromValue()));
    }

    @PutMapping("/proof-threshold")
    public SettingsView setProofThreshold(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody ProofThresholdForm form) {
        return view(service.setProofThreshold(sheetId.trim(), user.trim(), form.thresholdValue(), form.fromValue()));
    }

    @PutMapping("/permissions/{action}")
    public SettingsView setPermission(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @Pattern(regexp = "open|settle|void|reassign|close|reopen") String action,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PermissionForm form) {
        return view(service.setPermission(sheetId.trim(), user.trim(), action, form.rolesValue()));
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.IdClass;
import jakarta.persistence.Table;
import java.io.Serializable;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Objects;

/** The value a dated setting of a sheet takes from a date on (the floor, the late percent, the terms
 *  of the sheet and of each grade, the clerk limit, the cap); in force until a later from-date of the
 *  same key. A null value is blank: no limit, no cap. */
@Entity
@Table(name = "setting_value")
@IdClass(SettingValue.Key.class)
public class SettingValue {

    /** The key of a setting value: its sheet, setting and from-date. */
    public static class Key implements Serializable {
        private String sheetId;
        private String key;
        private LocalDate from;

        protected Key() {
        }

        public Key(String sheetId, String key, LocalDate from) {
            this.sheetId = sheetId;
            this.key = key;
            this.from = from;
        }

        @Override
        public boolean equals(Object o) {
            return o instanceof Key k && Objects.equals(sheetId, k.sheetId) && Objects.equals(key, k.key)
                    && Objects.equals(from, k.from);
        }

        @Override
        public int hashCode() {
            return Objects.hash(sheetId, key, from);
        }
    }

    @Id
    @Column(name = "sheet_id")
    private String sheetId;

    @Id
    @Column(name = "setting_key")
    private String key;

    @Id
    @Column(name = "from_date")
    private LocalDate from;

    @Column(name = "setting", precision = 14, scale = 2)
    private BigDecimal value;

    protected SettingValue() {
    }

    public SettingValue(String sheetId, String key, LocalDate from, BigDecimal value) {
        this.sheetId = sheetId;
        this.key = key;
        this.from = from;
        this.value = value;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getKey() {
        return key;
    }

    public LocalDate getFrom() {
        return from;
    }

    public BigDecimal getValue() {
        return value;
    }

    public void setValue(BigDecimal value) {
        this.value = value;
    }
}
package net.officefloor.hq.app.sheet;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.TreeMap;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import org.springframework.context.annotation.Lazy;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Loads sheets by id; a sheet that was never loaded before starts empty. */
@Service
public class SheetService {

    /** The grades a person can have, each of which may have terms of its own. */
    private static final List<String> GRADES = List.of("A", "B", "C");

    private final SheetRepository sheets;
    private final SettingValueRepository settingValues;
    private final SheetPermissionRepository permissions;
    /** Lazy: the rollup reads the sheet's today through this service. */
    private final Rollup rollup;
    private final Audit audit;

    public SheetService(SheetRepository sheets, SettingValueRepository settingValues,
            SheetPermissionRepository permissions, @Lazy Rollup rollup, Audit audit) {
        this.sheets = sheets;
        this.settingValues = settingValues;
        this.permissions = permissions;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The sheet with this id, created empty the first time it is loaded, its today the real date. */
    @Transactional
    public synchronized Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> sheets.save(new Sheet(id, user, LocalDate.now())));
    }

    /** The sheet's today: the date every date-dependent decision and default date on it uses. */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElseGet(LocalDate::now);
    }

    /** The next claim number on the sheet: 1 for its first opened claim, then 2, and so on. */
    @Transactional
    public int nextClaimNumber(String id) {
        if (sheets.advanceClaimNumber(id) != 1) {
            throw new IllegalStateException("No sheet " + id);
        }
        return sheets.lastClaimNumber(id);
    }

    /** The next X-number on the sheet, for a claim in no period opened under period numbering: 1,
     *  then 2, and so on. */
    @Transactional
    public int nextUnperiodNumber(String id) {
        if (sheets.advanceUnperiodNumber(id) != 1) {
            throw new IllegalStateException("No sheet " + id);
        }
        return sheets.lastUnperiodNumber(id);
    }

    /** Change the sheet's today; the figures it moves are recorded, with no record of its own. */
    @Transactional
    public synchronized Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = load(id, user);
        return rollup.tracking(id, user, () -> {
            sheet.setToday(today);
            return sheets.saveAndFlush(sheet);
        });
    }

    /** The floor a sheet starts with, in force before every from-date of its own. */
    public static final BigDecimal STARTING_FLOOR = new BigDecimal("1.00");
    /** The late percent a sheet starts with, in force before every from-date of its own. */
    public static final BigDecimal STARTING_LATE_PCT = new BigDecimal("0.00");
    /** The terms a sheet starts with, in force before every from-date of its own. */
    public static final int STARTING_TERMS = 14;

    /** The value a dated setting of the sheet has recorded in force on a day: the one with the latest
     *  from-date on or before it; empty when none is (the value itself is null when blank). */
    private Optional<SettingValue> inForce(String id, String key, LocalDate day) {
        return settingValues.findFirstBySheetIdAndKeyAndFromLessThanEqualOrderByFromDesc(id, key, day);
    }

    /** The values recorded for a dated setting of the sheet, earliest from-date first. */
    @Transactional(readOnly = true)
    public List<SettingValue> recorded(String id, String key) {
        return settingValues.findBySheetIdAndKeyOrderByFrom(id, key);
    }

    /** Record a dated setting's value from a date (the sheet's today when none is given), keeping the
     *  values already recorded (one from the same date is replaced); recorded in the audit even when
     *  it is unchanged, with the from-date at the end when one was given. */
    private Sheet record(String id, String user, String key, BigDecimal value, String shown, LocalDate from) {
        Sheet sheet = load(id, user);
        LocalDate on = from != null ? from : sheet.getToday();
        SettingValue v = settingValues.findById(new SettingValue.Key(id, key, on))
                .orElseGet(() -> new SettingValue(id, key, on, value));
        v.setValue(value);
        settingValues.saveAndFlush(v);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=" + key + " value=" + shown
                + (from != null ? " from=" + from : ""));
        return sheet;
    }

    /** The most due a clerk may settle on a claim on the sheet: the limit in force on the sheet's
     *  today; null when there is no limit. */
    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String id) {
        return inForce(id, "clerk-limit", today(id)).map(SettingValue::getValue).orElse(null);
    }

    /** Record the sheet's clerk limit (null: no limit) from a date (null: the sheet's today). */
    @Transactional
    public synchronized Sheet setClerkLimit(String id, String user, BigDecimal limit, LocalDate from) {
        return record(id, user, "clerk-limit", limit, limit == null ? "" : limit.setScale(2).toPlainString(), from);
    }

    /** The least live due a claim on the sheet dated on the day has: the floor in force on it, or
     *  else the sheet's starting floor. */
    @Transactional(readOnly = true)
    public BigDecimal floor(String id, LocalDate day) {
        return inForce(id, "floor", day).map(SettingValue::getValue).orElse(STARTING_FLOOR);
    }

    /** The floor in force on the sheet's today. */
    @Transactional(readOnly = true)
    public BigDecimal floor(String id) {
        return floor(id, today(id));
    }

    /** Record the sheet's floor from a date (null: the sheet's today), then the figures it moves. */
    @Transactional
    public synchronized Sheet setFloor(String id, String user, BigDecimal floor, LocalDate from) {
        load(id, user);
        return rollup.tracking(id, user,
                () -> record(id, user, "floor", floor, floor.setScale(2).toPlainString(), from));
    }

    /** The days after its date a claim on the sheet dated on the day is due by: the sheet's terms in
     *  force on it, or else its starting terms. */
    @Transactional(readOnly = true)
    public int terms(String id, LocalDate day) {
        return inForce(id, "terms", day).map(v -> v.getValue().intValue()).orElse(STARTING_TERMS);
    }

    /** The sheet's terms in force on its today. */
    @Transactional(readOnly = true)
    public int terms(String id) {
        return terms(id, today(id));
    }

    /** Record the sheet's terms from a date (null: the sheet's today). They change no claim's due-by,
     *  which is fixed when the claim is made. */
    @Transactional
    public synchronized Sheet setTerms(String id, String user, int terms, LocalDate from) {
        load(id, user);
        return rollup.tracking(id, user,
                () -> record(id, user, "terms", BigDecimal.valueOf(terms), String.valueOf(terms), from));
    }

    /** The terms each grade on the sheet has of its own in force on its today, by grade; a grade not
     *  in it takes the sheet's terms. */
    @Transactional(readOnly = true)
    public Map<String, Integer> gradeTerms(String id) {
        LocalDate today = today(id);
        Map<String, Integer> terms = new TreeMap<>();
        for (String grade : GRADES) {
            inForce(id, "terms-" + grade, today).ifPresent(v -> terms.put(grade, v.getValue().intValue()));
        }
        return terms;
    }

    /** The terms in force on a day for a grade on the sheet: its own in force on the day, or else the
     *  sheet's. */
    @Transactional(readOnly = true)
    public int termsFor(String id, String grade, LocalDate day) {
        return inForce(id, "terms-" + grade, day).map(v -> v.getValue().intValue())
                .orElseGet(() -> terms(id, day));
    }

    /** Record a grade's own terms from a date (null: the sheet's today). They change no claim's
     *  due-by, which is fixed when the claim is made. */
    @Transactional
    public synchronized Sheet setGradeTerms(String id, String user, String grade, int terms, LocalDate from) {
        return record(id, user, "terms-" + grade, BigDecimal.valueOf(terms), String.valueOf(terms), from);
    }

    /** The percent of its figure an overdue claim on the sheet dated on the day gains for every full
     *  30 days it is overdue: the late percent in force on it, or else the sheet's starting one. */
    @Transactional(readOnly = true)
    public BigDecimal latePct(String id, LocalDate day) {
        return inForce(id, "late-pct", day).map(SettingValue::getValue).orElse(STARTING_LATE_PCT);
    }

    /** The late percent in force on the sheet's today. */
    @Transactional(readOnly = true)
    public BigDecimal latePct(String id) {
        return latePct(id, today(id));
    }

    /** Record the sheet's late percent from a date (null: the sheet's today), then the figures it
     *  moves. */
    @Transactional
    public synchronized Sheet setLatePct(String id, String user, BigDecimal latePct, LocalDate from) {
        load(id, user);
        return rollup.tracking(id, user,
                () -> record(id, user, "late-pct", latePct, latePct.setScale(2).toPlainString(), from));
    }

    /** The sheet's policy date as set; null when it is blank (the sheet's today then stands in). */
    @Transactional(readOnly = true)
    public LocalDate policyDate(String id) {
        return sheets.findById(id).map(Sheet::getPolicyDate).orElse(null);
    }

    /** The policy date in force: the one set, or else the sheet's today. */
    @Transactional(readOnly = true)
    public LocalDate policyDateInForce(String id) {
        return sheets.findById(id).map(s -> s.getPolicyDate() != null ? s.getPolicyDate() : s.getToday())
                .orElseGet(LocalDate::now);
    }

    /** Change the sheet's policy date (null: blank, the sheet's today); recorded even when it is
     *  unchanged, then the figures it moves. */
    @Transactional
    public synchronized Sheet setPolicyDate(String id, String user, LocalDate policyDate) {
        Sheet sheet = load(id, user);
        return rollup.tracking(id, user, () -> {
            sheet.setPolicyDate(policyDate);
            Sheet saved = sheets.saveAndFlush(sheet);
            audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=policy-date value="
                    + (policyDate == null ? "" : policyDate.toString()));
            return saved;
        });
    }

    /** The sheet's period numbering from date; null when it is blank (off). */
    @Transactional(readOnly = true)
    public LocalDate periodNumberingFrom(String id) {
        return sheets.findById(id).map(Sheet::getPeriodNumberingFrom).orElse(null);
    }

    /** Whether a claim opened on the sheet now is numbered within its period: the setting is a date
     *  and the sheet's today is on or after it. */
    @Transactional(readOnly = true)
    public boolean periodNumbering(String id) {
        return sheets.findById(id)
                .map(s -> s.getPeriodNumberingFrom() != null && !s.getToday().isBefore(s.getPeriodNumberingFrom()))
                .orElse(false);
    }

    /** Change the sheet's period numbering from date (null: blank, off); recorded even when it is
     *  unchanged. It changes no figure, and no number already given. */
    @Transactional
    public synchronized Sheet setPeriodNumberingFrom(String id, String user, LocalDate from) {
        Sheet sheet = load(id, user);
        sheet.setPeriodNumberingFrom(from);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=period-numbering-from value="
                + (from == null ? "" : from.toString()));
