38	    /** The sheet with this id, created empty the first time it is loaded, its today the real date. */
39	    @Transactional
40	    public synchronized Sheet load(String id, String user) {
41	        return sheets.findById(id).orElseGet(() -> sheets.save(new Sheet(id, user, LocalDate.now())));
42	    }
43	
44	    /** The sheet's today: the date every date-dependent decision and default date on it uses. */
45	    @Transactional(readOnly = true)
46	    public LocalDate today(String id) {
47	        return sheets.findById(id).map(Sheet::getToday).orElseGet(LocalDate::now);
48	    }
49	
50	    /** The next claim number on the sheet: 1 for its first opened claim, then 2, and so on. */
51	    @Transactional
52	    public int nextClaimNumber(String id) {
53	        if (sheets.advanceClaimNumber(id) != 1) {
54	            throw new IllegalStateException("No sheet " + id);
55	        }
56	        return sheets.lastClaimNumber(id);
57	    }
