61	    @Transactional
62	    public int nextUnperiodNumber(String id) {
63	        if (sheets.advanceUnperiodNumber(id) != 1) {
64	            throw new IllegalStateException("No sheet " + id);
65	        }
66	        return sheets.lastUnperiodNumber(id);
67	    }
