92	    /** The values recorded for a dated setting of the sheet, earliest from-date first. */
93	    @Transactional(readOnly = true)
94	    public List<SettingValue> recorded(String id, String key) {
95	        return settingValues.findBySheetIdAndKeyOrderByFrom(id, key);
96	    }
