151	        return inForce(id, "terms", day).map(v -> v.getValue().intValue()).orElse(STARTING_TERMS);
152	    }
153	
154	    /** The sheet's terms in force on its today. */
155	    @Transactional(readOnly = true)
156	    public int terms(String id) {
157	        return terms(id, today(id));
158	    }
159	
160	    /** Record the sheet's terms from a date (null: the sheet's today). They change no claim's due-by,
161	     *  which is fixed when the claim is made. */
162	    @Transactional
163	    public synchronized Sheet setTerms(String id, String user, int terms, LocalDate from) {
