169	    /** The terms each grade on the sheet has of its own in force on its today, by grade; a grade not
170	     *  in it takes the sheet's terms. */
171	    @Transactional(readOnly = true)
172	    public Map<String, Integer> gradeTerms(String id) {
173	        LocalDate today = today(id);
174	        Map<String, Integer> terms = new TreeMap<>();
175	        for (String grade : GRADES) {
176	            inForce(id, "terms-" + grade, today).ifPresent(v -> terms.put(grade, v.getValue().intValue()));
177	        }
178	        return terms;
179	    }
180	
181	    /** The terms in force on a day for a grade on the sheet: its own in force on the day, or else the
182	     *  sheet's. */
183	    @Transactional(readOnly = true)
184	    public int termsFor(String id, String grade, LocalDate day) {
185	        return inForce(id, "terms-" + grade, day).map(v -> v.getValue().intValue())
186	                .orElseGet(() -> terms(id, day));
187	    }
188	
189	    /** Record a grade's own terms from a date (null: the sheet's today). They change no claim's
190	     *  due-by, which is fixed when the claim is made. */
191	    @Transactional
192	    public synchronized Sheet setGradeTerms(String id, String user, String grade, int terms, LocalDate from) {
193	        return record(id, user, "terms-" + grade, BigDecimal.valueOf(terms), String.valueOf(terms), from);
194	    }
195	
196	    /** The percent of its figure an overdue claim on the sheet dated on the day gains for every full
197	     *  30 days it is overdue: the late percent in force on it, or else the sheet's starting one. */
198	    @Transactional(readOnly = true)
199	    public BigDecimal latePct(String id, LocalDate day) {
200	        return inForce(id, "late-pct", day).map(SettingValue::getValue).orElse(STARTING_LATE_PCT);
201	    }
202	
203	    /** The late percent in force on the sheet's today. */
204	    @Transactional(readOnly = true)
205	    public BigDecimal latePct(String id) {
206	        return latePct(id, today(id));
207	    }
208	
209	    /** Record the sheet's late percent from a date (null: the sheet's today), then the figures it
210	     *  moves. */
211	    @Transactional
212	    public synchronized Sheet setLatePct(String id, String user, BigDecimal latePct, LocalDate from) {
213	        load(id, user);
214	        return rollup.tracking(id, user,
215	                () -> record(id, user, "late-pct", latePct, latePct.setScale(2).toPlainString(), from));
216	    }
217	
218	    /** The sheet's policy date as set; null when it is blank (the sheet's today then stands in). */
219	    @Transactional(readOnly = true)
220	    public LocalDate policyDate(String id) {
221	        return sheets.findById(id).map(Sheet::getPolicyDate).orElse(null);
222	    }
223	
224	    /** The policy date in force: the one set, or else the sheet's today. */
225	    @Transactional(readOnly = true)
226	    public LocalDate policyDateInForce(String id) {
227	        return sheets.findById(id).map(s -> s.getPolicyDate() != null ? s.getPolicyDate() : s.getToday())
228	                .orElseGet(LocalDate::now);
229	    }
230	
231	    /** Change the sheet's policy date (null: blank, the sheet's today); recorded even when it is
232	     *  unchanged, then the figures it moves. */
233	    @Transactional
234	    public synchronized Sheet setPolicyDate(String id, String user, LocalDate policyDate) {
235	        Sheet sheet = load(id, user);
236	        return rollup.tracking(id, user, () -> {
237	            sheet.setPolicyDate(policyDate);
238	            Sheet saved = sheets.saveAndFlush(sheet);
239	            audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=policy-date value="
240	                    + (policyDate == null ? "" : policyDate.toString()));
241	            return saved;
242	        });
243	    }
244	
245	    /** The sheet's period numbering from date; null when it is blank (off). */
246	    @Transactional(readOnly = true)
247	    public LocalDate periodNumberingFrom(String id) {
248	        return sheets.findById(id).map(Sheet::getPeriodNumberingFrom).orElse(null);
249	    }
250	
251	    /** Whether a claim opened on the sheet now is numbered within its period: the setting is a date
252	     *  and the sheet's today is on or after it. */
253	    @Transactional(readOnly = true)
254	    public boolean periodNumbering(String id) {
255	        return sheets.findById(id)
256	                .map(s -> s.getPeriodNumberingFrom() != null && !s.getToday().isBefore(s.getPeriodNumberingFrom()))
257	                .orElse(false);
258	    }
259	
260	    /** Change the sheet's period numbering from date (null: blank, off); recorded even when it is
261	     *  unchanged. It changes no figure, and no number already given. */
262	    @Transactional
263	    public synchronized Sheet setPeriodNumberingFrom(String id, String user, LocalDate from) {
264	        Sheet sheet = load(id, user);
265	        sheet.setPeriodNumberingFrom(from);
266	        Sheet saved = sheets.saveAndFlush(sheet);
267	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=period-numbering-from value="
268	                + (from == null ? "" : from.toString()));
269	        return saved;
270	    }
271	
272	    /** The most a person's due-total on the sheet comes to: the cap in force on the sheet's today;
273	     *  null when there is no cap. */
274	    @Transactional(readOnly = true)
275	    public BigDecimal cap(String id) {
276	        return inForce(id, "cap", today(id)).map(SettingValue::getValue).orElse(null);
277	    }
278	
279	    /** Record the sheet's cap (null: no cap) from a date (null: the sheet's today), then the figures
280	     *  it moves. */
281	    @Transactional
282	    public synchronized Sheet setCap(String id, String user, BigDecimal cap, LocalDate from) {
283	        load(id, user);
284	        return rollup.tracking(id, user,
285	                () -> record(id, user, "cap", cap, cap == null ? "" : cap.setScale(2).toPlainString(), from));
286	    }
287	
288	    /** The due above which a claim on the sheet dated on the day needs a proof before it is settled
289	     *  or approved: the proof threshold in force on it; null when there is none. */
290	    @Transactional(readOnly = true)
291	    public BigDecimal proofThreshold(String id, LocalDate day) {
292	        return inForce(id, "proof-threshold", day).map(SettingValue::getValue).orElse(null);
293	    }
294	
295	    /** The proof threshold in force on the sheet's today. */
296	    @Transactional(readOnly = true)
297	    public BigDecimal proofThreshold(String id) {
298	        return proofThreshold(id, today(id));
299	    }
300	
301	    /** Record the sheet's proof threshold (null: none) from a date (null: the sheet's today). It
302	     *  changes no figure. */
303	    @Transactional
304	    public synchronized Sheet setProofThreshold(String id, String user, BigDecimal threshold, LocalDate from) {
305	        return record(id, user, "proof-threshold", threshold,
306	                threshold == null ? "" : threshold.setScale(2).toPlainString(), from);
307	    }
308	
309	    /** The actions the permission matrix covers. */
310	    public static final List<String> ACTIONS = List.of("open", "settle", "void", "reassign", "close", "reopen");
311	
312	    /** The roles that may take each action under the standing rule (a blank entry in the matrix). */
313	    private static final Map<String, List<String>> STANDING_PERMISSIONS = Map.of(
314	            "open", List.of("clerk", "steward"), "settle", List.of("clerk", "steward"),
315	            "void", List.of("clerk", "steward"), "close", List.of("clerk", "steward"),
316	            "reassign", List.of("steward"), "reopen", List.of("steward"));
317	
318	    /** The permission matrix as set on the sheet: for each action, the comma separated roles that may
319	     *  take it, blank ("") when it keeps the standing rule. */
320	    @Transactional(readOnly = true)
321	    public Map<String, String> permissions(String id) {
322	        Map<String, String> matrix = new TreeMap<>();
323	        for (String action : ACTIONS) {
324	            matrix.put(action, "");
325	        }
326	        for (SheetPermission p : permissions.findBySheetId(id)) {
327	            matrix.put(p.getAction(), p.getRoles());
328	        }
329	        return matrix;
330	    }
331	
332	    /** The roles that may take an action on the sheet: those set in the matrix, or else the standing
333	     *  rule's. */
334	    @Transactional(readOnly = true)
335	    public List<String> rolesAllowed(String id, String action) {
336	        return permissions.findById(new SheetPermission.Key(id, action))
337	                .map(p -> List.of(p.getRoles().split(",")))
338	                .orElse(STANDING_PERMISSIONS.get(action));
339	    }
340	
341	    /** Set the roles (a comma separated list; blank: the standing rule) that may take an action on the
342	     *  sheet; recorded even when it is unchanged. */
343	    @Transactional
344	    public synchronized Sheet setPermission(String id, String user, String action, String roles) {
345	        Sheet sheet = load(id, user);
346	        if (roles.isEmpty()) {
347	            permissions.deleteById(new SheetPermission.Key(id, action));
348	        } else {
349	            SheetPermission p = permissions.findById(new SheetPermission.Key(id, action))
350	                    .orElseGet(() -> new SheetPermission(id, action, roles));
351	            p.setRoles(roles);
352	            permissions.saveAndFlush(p);
353	        }
354	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=perm-" + action + " value=" + roles);
355	        return sheet;
356	    }
357	}
