29	        <label for="setting-proof-threshold">Proof threshold (a claim due above it needs a proof; blank: none)</label>
30	        <input id="setting-proof-threshold" data-testid="setting-proof-threshold" formControlName="proofThreshold"
31	               inputmode="decimal" />
32	        <label for="setting-proof-threshold-from">Proof threshold from (blank: today)</label>
33	        <input id="setting-proof-threshold-from" data-testid="setting-proof-threshold-from" type="date"
34	               formControlName="proofThresholdFrom" />
35	        <label for="setting-floor">Floor</label>
36	        <input id="setting-floor" data-testid="setting-floor" formControlName="floor" inputmode="decimal" />
