41	        <label for="setting-terms-from">Terms from (blank: today)</label>
42	        <input id="setting-terms-from" data-testid="setting-terms-from" type="date" formControlName="termsFrom" />
43	        <fieldset formGroupName="gradeTerms">
44	          <legend>Terms per grade (days; blank: the sheet's terms)</legend>
45	          @for (g of grades; track g) {
46	            <label [for]="'setting-terms-' + g">Grade {{ g }}</label>
47	            <input [id]="'setting-terms-' + g" [attr.data-testid]="'setting-terms-' + g" [formControlName]="g"
48	                   inputmode="numeric" />
49	            <label [for]="'setting-terms-' + g + '-from'">Grade {{ g }} terms from (blank: today)</label>
50	            <input [id]="'setting-terms-' + g + '-from'" [attr.data-testid]="'setting-terms-' + g + '-from'"
51	                   type="date" [formControlName]="g + 'From'" />
52	          }
53	        </fieldset>
54	        <label for="setting-late-pct">Late percent (per 30 days overdue)</label>
55	        <input id="setting-late-pct" data-testid="setting-late-pct" formControlName="latePct" inputmode="decimal" />
56	        <label for="setting-late-pct-from">Late percent from (blank: today)</label>
57	        <input id="setting-late-pct-from" data-testid="setting-late-pct-from" type="date" formControlName="latePctFrom" />
58	        <label for="setting-policy-date">Policy date (claims dated before it round half up; blank: today)</label>
59	        <input id="setting-policy-date" data-testid="setting-policy-date" type="date" formControlName="policyDate" />
60	        <label for="setting-period-numbering-from">Period numbering from (claims opened from it are numbered within their period; blank: off)</label>
61	        <input id="setting-period-numbering-from" data-testid="setting-period-numbering-from" type="date"
62	               formControlName="periodNumberingFrom" />
63	        <fieldset formGroupName="permissions">
64	          <legend>Permissions (roles that may take each action, comma separated; blank: the standing rule)</legend>
65	          @for (a of permActions; track a) {
66	            <label [for]="'setting-perm-' + a">{{ a }} (blank: {{ standing[a] }})</label>
67	            <input [id]="'setting-perm-' + a" [attr.data-testid]="'setting-perm-' + a" [formControlName]="a" />
68	          }
69	        </fieldset>
70	        <button type="submit" data-testid="settings-save">Save settings</button>
71	        @if (settingsError()) {
72	          <p role="alert" data-testid="settings-error">{{ settingsError() }}</p>
73	        }
74	      </form>
75	      <p>Clerk limit in force: <span data-testid="setting-clerk-limit-current">{{ clerkLimit() ?? '' }}</span></p>
76	      <p>Cap in force: <span data-testid="setting-cap-current">{{ cap() ?? '' }}</span></p>
77	      <p>Proof threshold in force: <span data-testid="setting-proof-threshold-current">{{ proofThreshold() ?? '' }}</span></p>
78	      <p>Floor in force: <span data-testid="setting-floor-current">{{ floor() ?? '' }}</span></p>
79	      <p>Terms in force: <span data-testid="setting-terms-current">{{ terms() ?? '' }}</span></p>
80	      @for (g of grades; track g) {
81	        <p>Terms in force for grade {{ g }}:
82	          <span [attr.data-testid]="'setting-terms-' + g + '-current'">{{ termsOf(g) ?? '' }}</span></p>
83	      }
84	      <p>Late percent in force: <span data-testid="setting-late-pct-current">{{ latePct() ?? '' }}</span></p>
85	      <p>Policy date in force: <span data-testid="setting-policy-date-current">{{ policyDate() ?? '' }}</span></p>
86	      <p>Period numbering from: <span data-testid="setting-period-numbering-from-current">{{ periodNumberingFrom() ?? '' }}</span></p>
87	      @for (a of permActions; track a) {
88	        <p>Roles that may {{ a }}:
89	          <span [attr.data-testid]="'setting-perm-' + a + '-current'">{{ permissions()[a] ?? '' }}</span></p>
90	      }
91	      <h3>Roles</h3>
92	      <form data-testid="role-form" [formGroup]="roleForm" (ngSubmit)="saveRole()">
93	        <label for="role-form-user">User</label>
94	        <input id="role-form-user" data-testid="role-form-user" formControlName="user" />
95	        <label for="role-form-role">Role</label>
96	        <input id="role-form-role" data-testid="role-form-role" formControlName="role" list="role-names" />
97	        <datalist id="role-names">
98	          @for (r of roleNames; track r) {
99	            <option [value]="r"></option>
100	          }
101	        </datalist>
102	        <button type="submit" data-testid="role-form-submit">Set role</button>
103	        @if (roleError()) {
104	          <p role="alert" data-testid="role-form-error">{{ roleError() }}</p>
105	        }
106	      </form>
107	      <table data-testid="roles">
108	        <caption>Roles given (any other name is a clerk)</caption>
109	        <thead>
110	          <tr><th scope="col">User</th><th scope="col">Role</th></tr>
111	        </thead>
112	        <tbody>
113	          @for (r of roles(); track r.user) {
114	            <tr [attr.data-testid]="'role-row-' + r.user">
115	              <th scope="row" data-testid="role-user">{{ r.user }}</th>
116	              <td data-testid="role-value">{{ r.role }}</td>
117	            </tr>
118	          }
119	        </tbody>
120	      </table>
121	    </section>
122	  `,
123	})
124	export class SettingsForm {
125	  private readonly api = inject(SheetSettings);
126	  private readonly session = inject(Session);
127	
128	  protected readonly roleNames = ROLES;
129	  protected readonly clerkLimit = signal<string | null>(null);
130	  protected readonly cap = signal<string | null>(null);
131	  protected readonly proofThreshold = signal<string | null>(null);
132	  protected readonly floor = signal<string | null>(null);
133	  protected readonly terms = signal<number | null>(null);
134	  protected readonly grades: Grade[] = ['A', 'B', 'C'];
135	  /** The terms each grade has of its own; a grade not in it takes the sheet's terms. */
136	  protected readonly gradeTerms = signal<Partial<Record<Grade, number>>>({});
137	  protected readonly latePct = signal<string | null>(null);
138	  protected readonly policyDate = signal<string | null>(null);
139	  protected readonly periodNumberingFrom = signal<string | null>(null);
140	  protected readonly permActions = PERM_ACTIONS;
141	  protected readonly standing = STANDING_PERMISSIONS;
142	  /** The permission matrix as set; an action's entry is blank when it keeps the standing rule. */
143	  protected readonly permissions = signal<Partial<Record<PermAction, string>>>({});
144	  protected readonly roles = signal<Role[]>([]);
145	  protected readonly settingsError = signal('');
146	  protected readonly roleError = signal('');
147	  /** Whether a submit is waiting for its answer: a second submit meanwhile is ignored. */
148	  private submitting = false;
149	  /** Only the newest read of the sheet may show: a load overtaken by another is dropped. */
150	  private reads = 0;
151	  protected readonly settingsForm = new FormGroup({
152	    clerkLimit: new FormControl('', { nonNullable: true }),
153	    clerkLimitFrom: new FormControl('', { nonNullable: true }),
154	    cap: new FormControl('', { nonNullable: true }),
155	    capFrom: new FormControl('', { nonNullable: true }),
156	    proofThreshold: new FormControl('', { nonNullable: true }),
157	    proofThresholdFrom: new FormControl('', { nonNullable: true }),
158	    floor: new FormControl('', { nonNullable: true }),
159	    floorFrom: new FormControl('', { nonNullable: true }),
160	    terms: new FormControl('', { nonNullable: true }),
161	    termsFrom: new FormControl('', { nonNullable: true }),
162	    gradeTerms: new FormGroup({
163	      A: new FormControl('', { nonNullable: true }),
164	      AFrom: new FormControl('', { nonNullable: true }),
165	      B: new FormControl('', { nonNullable: true }),
166	      BFrom: new FormControl('', { nonNullable: true }),
167	      C: new FormControl('', { nonNullable: true }),
168	      CFrom: new FormControl('', { nonNullable: true }),
169	    }),
170	    latePct: new FormControl('', { nonNullable: true }),
171	    latePctFrom: new FormControl('', { nonNullable: true }),
172	    policyDate: new FormControl('', { nonNullable: true }),
173	    periodNumberingFrom: new FormControl('', { nonNullable: true }),
174	    permissions: new FormGroup({
175	      open: new FormControl('', { nonNullable: true }),
176	      settle: new FormControl('', { nonNullable: true }),
177	      void: new FormControl('', { nonNullable: true }),
178	      reassign: new FormControl('', { nonNullable: true }),
179	      close: new FormControl('', { nonNullable: true }),
180	      reopen: new FormControl('', { nonNullable: true }),
181	    }),
182	  });
183	  protected readonly roleForm = new FormGroup({
184	    user: new FormControl('', { nonNullable: true }),
185	    role: new FormControl('', { nonNullable: true }),
186	  });
187	
188	  constructor() {
189	    this.settingsForm.valueChanges.subscribe(() => this.settingsError.set(''));
190	    this.roleForm.valueChanges.subscribe(() => this.roleError.set(''));
191	    effect(() => {
192	      this.session.loads();
193	      this.session.today(); // what is in force follows the sheet's today
194	      const sheetId = this.session.sheetId();
195	      this.clerkLimit.set(null);
196	      this.cap.set(null);
197	      this.proofThreshold.set(null);
198	      this.floor.set(null);
199	      this.terms.set(null);
200	      this.gradeTerms.set({});
201	      this.latePct.set(null);
202	      this.policyDate.set(null);
203	      this.periodNumberingFrom.set(null);
204	      this.permissions.set({});
205	      this.roles.set([]);
206	      if (sheetId) void this.reload(sheetId);
207	    });
208	  }
209	
210	  /** Save the settings changed since the last save (typed into, or entered and left, which an
211	   *  unchanged blank field may be); all of them when none was. */
212	  protected async saveSettings(): Promise<void> {
213	    if (this.submitting) return;
214	    this.settingsError.set('');
215	    const { clerkLimit, clerkLimitFrom, cap, capFrom, proofThreshold, proofThresholdFrom, floor, floorFrom, terms, termsFrom, gradeTerms, latePct,
216	      latePctFrom, policyDate, periodNumberingFrom, permissions } = this.settingsForm.controls;
217	    const changed = (...cs: AbstractControl[]) => cs.some((c) => c.dirty || c.touched);
218	    const none = !changed(clerkLimit, clerkLimitFrom) && !changed(cap, capFrom)
219	      && !changed(proofThreshold, proofThresholdFrom) && !changed(floor, floorFrom)
220	      && !changed(terms, termsFrom) && !changed(gradeTerms) && !changed(latePct, latePctFrom) && !changed(policyDate)
221	      && !changed(periodNumberingFrom) && !changed(permissions);
222	    /** A from-date typed, or null when blank (the sheet's today). */
223	    const from = (c: AbstractControl<string>) => c.value.trim() || null;
224	    const fromsToSave: AbstractControl<string>[] = [];
225	    const limitValue = clerkLimit.value.trim();
226	    const capValue = cap.value.trim();
227	    const saveCap = changed(cap, capFrom) || (none && capValue !== '');
228	    const thresholdValue = proofThreshold.value.trim();
229	    const saveThreshold = changed(proofThreshold, proofThresholdFrom) || (none && thresholdValue !== '');
230	    const floorValue = floor.value.trim();
231	    const saveLimit = none || changed(clerkLimit, clerkLimitFrom);
232	    const saveFloor = none || changed(floor, floorFrom);
233	    const termsValue = terms.value.trim();
234	    const saveTerms = none || changed(terms, termsFrom);
235	    const gradeTermsToSave = this.grades
236	      .map((g) => ({
237	        grade: g, control: gradeTerms.controls[g], fromControl: gradeTerms.controls[`${g}From`],
238	        value: gradeTerms.controls[g].value.trim(),
239	      }))
240	      .filter((t) => (none || changed(t.control, t.fromControl)) && t.value !== '');
241	    const latePctValue = latePct.value.trim();
242	    const saveLatePct = none || changed(latePct, latePctFrom);
243	    const policyDateValue = policyDate.value.trim();
244	    const savePolicyDate = none || changed(policyDate);
245	    const numberingValue = periodNumberingFrom.value.trim();
246	    const saveNumbering = none || changed(periodNumberingFrom);
247	    const permsToSave = this.permActions
248	      .map((a) => ({ action: a, control: permissions.controls[a], value: permissions.controls[a].value.trim() }))
249	      .filter((p) => changed(p.control) || (none && p.value !== ''));
250	    if (saveLimit) fromsToSave.push(clerkLimitFrom);
251	    if (saveCap) fromsToSave.push(capFrom);
252	    if (saveThreshold) fromsToSave.push(proofThresholdFrom);
253	    if (saveFloor && floorValue !== '') fromsToSave.push(floorFrom);
254	    if (saveTerms && termsValue !== '') fromsToSave.push(termsFrom);
255	    gradeTermsToSave.forEach((t) => fromsToSave.push(t.fromControl));
256	    if (saveLatePct && latePctValue !== '') fromsToSave.push(latePctFrom);
257	    if (fromsToSave.some((c) => c.value.trim() !== '' && !POLICY_DATE.test(c.value.trim()))) {
258	      this.settingsError.set('Enter a from-date, or leave it blank for the sheet\'s today.');
259	      return;
260	    }
261	    if (saveLimit && limitValue !== '' && !LIMIT.test(limitValue)) {
262	      this.settingsError.set('Enter a clerk limit of 0.00 or more with up to two decimals, or leave it blank for no limit.');
263	      return;
264	    }
265	    if (saveCap && capValue !== '' && !LIMIT.test(capValue)) {
266	      this.settingsError.set('Enter a cap of 0.00 or more with up to two decimals, or leave it blank for no cap.');
267	      return;
268	    }
269	    if (saveThreshold && thresholdValue !== '' && !LIMIT.test(thresholdValue)) {
270	      this.settingsError.set('Enter a proof threshold of 0.00 or more with up to two decimals, or leave it blank for none.');
271	      return;
272	    }
273	    if (saveFloor && !(none && floorValue === '') && !LIMIT.test(floorValue)) {
274	      this.settingsError.set('Enter a floor of 0.00 or more with up to two decimals.');
275	      return;
276	    }
277	    if (saveTerms && !(none && termsValue === '') && !TERMS.test(termsValue)) {
278	      this.settingsError.set('Enter terms of 0 or more whole days.');
279	      return;
280	    }
281	    if (gradeTermsToSave.some((t) => !TERMS.test(t.value))) {
282	      this.settingsError.set('Enter terms for a grade of 0 or more whole days, or leave them blank.');
283	      return;
284	    }
285	    if (saveLatePct && !(none && latePctValue === '') && !LATE_PCT.test(latePctValue)) {
286	      this.settingsError.set('Enter a late percent of 0.00 or more with up to two decimals.');
287	      return;
288	    }
289	    if (savePolicyDate && policyDateValue !== '' && !POLICY_DATE.test(policyDateValue)) {
290	      this.settingsError.set('Enter a policy date, or leave it blank for the sheet\'s today.');
291	      return;
292	    }
293	    if (saveNumbering && numberingValue !== '' && !POLICY_DATE.test(numberingValue)) {
294	      this.settingsError.set('Enter a period numbering from date, or leave it blank for off.');
295	      return;
296	    }
297	    if (permsToSave.some((p) => p.value !== '' && !PERM_ROLES.test(p.value))) {
298	      this.settingsError.set('Enter the roles that may take an action as clerk, steward or both, comma separated, or leave it blank for the standing rule.');
299	      return;
300	    }
301	    this.submitting = true;
302	    try {
303	      if (saveLimit) {
304	        const saved = await this.api.setClerkLimit(limitValue === '' ? null : limitValue, from(clerkLimitFrom));
305	        this.clerkLimit.set(saved.clerkLimit);
306	        for (const c of [clerkLimit, clerkLimitFrom]) {
307	          c.markAsPristine();
308	          c.markAsUntouched();
309	        }
310	      }
311	      if (saveCap) {
312	        const saved = await this.api.setCap(capValue === '' ? null : capValue, from(capFrom));
313	        this.cap.set(saved.cap);
314	        for (const c of [cap, capFrom]) {
315	          c.markAsPristine();
316	          c.markAsUntouched();
317	        }
318	      }
319	      if (saveThreshold) {
320	        const saved = await this.api.setProofThreshold(thresholdValue === '' ? null : thresholdValue,
321	          from(proofThresholdFrom));
322	        this.proofThreshold.set(saved.proofThreshold);
323	        for (const c of [proofThreshold, proofThresholdFrom]) {
324	          c.markAsPristine();
325	          c.markAsUntouched();
326	        }
327	      }
328	      if (saveFloor && floorValue !== '') {
329	        const saved = await this.api.setFloor(floorValue, from(floorFrom));
330	        this.floor.set(saved.floor);
331	        for (const c of [floor, floorFrom]) {
332	          c.markAsPristine();
333	          c.markAsUntouched();
334	        }
335	      }
336	      if (saveTerms && termsValue !== '') {
337	        const saved = await this.api.setTerms(termsValue, from(termsFrom));
338	        this.terms.set(saved.terms);
339	        for (const c of [terms, termsFrom]) {
340	          c.markAsPristine();
341	          c.markAsUntouched();
342	        }
343	      }
344	      for (const t of gradeTermsToSave) {
345	        const saved = await this.api.setGradeTerms(t.grade, t.value, from(t.fromControl));
346	        this.gradeTerms.set(saved.gradeTerms);
347	        for (const c of [t.control, t.fromControl]) {
348	          c.markAsPristine();
349	          c.markAsUntouched();
350	        }
351	      }
352	      if (saveLatePct && latePctValue !== '') {
353	        const saved = await this.api.setLatePct(latePctValue, from(latePctFrom));
354	        this.latePct.set(saved.latePct);
355	        for (const c of [latePct, latePctFrom]) {
356	          c.markAsPristine();
357	          c.markAsUntouched();
358	        }
359	      }
360	      if (savePolicyDate) {
361	        const saved = await this.api.setPolicyDate(policyDateValue === '' ? null : policyDateValue);
362	        this.policyDate.set(saved.policyDate);
363	        policyDate.markAsPristine();
364	        policyDate.markAsUntouched();
365	      }
366	      if (saveNumbering) {
367	        const saved = await this.api.setPeriodNumberingFrom(numberingValue === '' ? null : numberingValue);
368	        this.periodNumberingFrom.set(saved.periodNumberingFrom);
369	        periodNumberingFrom.markAsPristine();
370	        periodNumberingFrom.markAsUntouched();
371	      }
372	      for (const p of permsToSave) {
373	        const saved = await this.api.setPermission(p.action, p.value === '' ? null : p.value);
374	        this.permissions.set(saved.permissions);
375	        p.control.markAsPristine();
376	        p.control.markAsUntouched();
377	      }
378	      // a blank field entered and left, and not saved, is not taken as changed by the next save
379	      this.settingsForm.markAsUntouched();
380	    } catch {
381	      this.settingsError.set('The settings could not be saved.');
382	    } finally {
383	      this.submitting = false;
384	    }
385	  }
386	
387	  /** The terms in force for a grade: its own, or else the sheet's. */
388	  protected termsOf(g: Grade): number | null {
389	    return this.gradeTerms()[g] ?? this.terms();
390	  }
391	
392	  protected async saveRole(): Promise<void> {
393	    if (this.submitting) return;
394	    this.roleError.set('');
395	    const user = this.roleForm.getRawValue().user.trim();
396	    const role = this.roleForm.getRawValue().role.trim();
397	    if (user === '') {
398	      this.roleError.set('Enter a user name.');
399	      return;
400	    }
401	    if (!(ROLES as string[]).includes(role)) {
402	      this.roleError.set('Choose a role of clerk, steward or viewer.');
403	      return;
404	    }
405	    this.submitting = true;
406	    try {
407	      const saved = await this.api.setRole(user, role as RoleName);
408	      this.roles.update((rs) =>
409	        [...rs.filter((r) => r.user !== saved.user), saved].sort((a, b) => a.user.localeCompare(b.user)),
410	      );
411	      this.roleForm.reset({ user: '', role: '' }, { emitEvent: false });
412	    } catch {
413	      this.roleError.set('The role could not be set.');
414	    } finally {
415	      this.submitting = false;
416	    }
417	  }
418	
419	  private async reload(sheetId: string): Promise<void> {
420	    const read = ++this.reads;
421	    try {
422	      const [settings, roles] = await Promise.all([this.api.get(sheetId), this.api.roles(sheetId)]);
423	      if (read === this.reads) {
424	        this.clerkLimit.set(settings.clerkLimit);
425	        this.cap.set(settings.cap);
426	        this.proofThreshold.set(settings.proofThreshold);
427	        this.floor.set(settings.floor);
428	        this.terms.set(settings.terms);
429	        this.gradeTerms.set(settings.gradeTerms);
430	        this.latePct.set(settings.latePct);
431	        this.policyDate.set(settings.policyDate);
432	        this.periodNumberingFrom.set(settings.periodNumberingFrom);
433	        this.permissions.set(settings.permissions);
434	        this.roles.set(roles);
